  function pageName(){if(ui.page==='project')return projectBy(ui.projectId)?.name||'Project';if(ui.page==='cycle')return ui.cycleName||'Cycle';if(ui.page==='custom')return data.views.find(v=>v.id===ui.viewId)?.name||'View';if(ui.page==='initiative')return data.initiatives.find(i=>i.id===ui.initiativeId)?.name||'Initiative';return ({my:'My issues',inbox:'Inbox',issues:'Issues',projects:'Projects','team-projects':'Projects',cycles:'Cycles',views:'Views',initiatives:'Initiatives',requests:'Triage',documents:'Documents',customers:'Customers',releases:'Releases',templates:'Templates',statuses:'Statuses',settings:'Settings',search:'Search',team:selectedTeamName(),members:'Members',teams:'Teams',dashboards:'Dashboards',overview:'Overview',announcements:'Announcements',applications:'App suggestions',integrations:'Integrations',security:'Security',audit:'Audit log',deleted:'Recently deleted'})[ui.page]||'Issues'}
