  function filteredIssues(){let list=[...data.issues];if(ui.page==='my'){if(ui.tab==='Assigned')list=list.filter(i=>i.assigneeId===enterprise.user.id||(!i.assigneeId&&i.assignee===currentUserName));else if(ui.tab==='Created')list=list.filter(i=>i.createdById===enterprise.user.id||(!i.createdById&&i.createdBy===currentUserName));else if(ui.tab==='Subscribed')list=list.filter(i=>(enterprise.mySubscribedIds||[]).includes(i.id));else if(ui.tab==='Activity')list=list.filter(i=>(enterprise.myActivityIds||[]).includes(i.id))}if(!['requests','custom'].includes(ui.page))list=list.filter(i=>i.status!=='Triage');if(['issues','cycles','cycle','team','team-projects'].includes(ui.page))list=list.filter(i=>i.teamId===ui.teamId);if(ui.page==='project')list=list.filter(i=>i.projectId===ui.projectId);if(ui.page==='cycle')list=list.filter(i=>i.cycle===ui.cycleName);if(ui.page==='custom'){let v=data.views.find(x=>x.id===ui.viewId);if(v?.type==='priority')list=list.filter(i=>['Urgent','High'].includes(i.priority));if(v?.type==='unassigned')list=list.filter(i=>!i.assignee);if(v?.type==='active')list=list.filter(i=>['unstarted','started'].includes(statusCategory(i.status,i.teamId)))}if(ui.page==='custom'&&window.LinearWorkflows)list=window.LinearWorkflows.filterViewIssues(list,data.views.find(v=>v.id===ui.viewId));if(ui.tab==='Active'&&ui.page!=='my')list=list.filter(i=>['unstarted','started'].includes(statusCategory(i.status,i.teamId)));if(ui.tab==='Backlog'&&ui.page!=='my')list=list.filter(i=>statusCategory(i.status,i.teamId)==='backlog');if(ui.tab==='Completed'&&ui.page!=='my')list=list.filter(completed);if(!ui.showSubissues)list=list.filter(i=>!i.parentId);if(!ui.showCompleted&&ui.tab!=='Completed')list=list.filter(i=>!completed(i));for(const [key,value] of Object.entries(ui.filters)){if(!value)continue;list=list.filter(i=>{if(key==='labels')return (i.labels||[]).includes(value);if(key==='content')return `${i.title} ${i.description||''}`.toLowerCase().includes(value.toLowerCase());if(key==='creator')return (i.createdBy||'Unassigned')===value;if(key==='dueDate'){const d=i.dueDate||'';const today=new Date().toISOString().slice(0,10);const week=new Date(Date.now()+7*86400000).toISOString().slice(0,10);return value==='No due date'?!d:value==='Overdue'?!!d&&d<today:value==='Today'?d===today:!!d&&d>=today&&d<=week}if(key==='relations')return value==='Has parent'?!!i.parentId:value==='Has subissues'?data.issues.some(x=>x.parentId===i.id):value==='Has related issues'?!!i.relatedIds?.length:!!i.blockedByIds?.length;if(key==='assignee')return (i.assignee||'Unassigned')===value;if(key==='project')return (i.project||'No project')===value;if(key==='cycle')return (i.cycle||'No cycle')===value;return i[key]===value})}if(ui.search)list=list.filter(i=>(i.title+' '+i.id+' '+i.description).toLowerCase().includes(ui.search.toLowerCase()));if(ui.sort==='Priority')list.sort((a,b)=>priorities.indexOf(a.priority)-priorities.indexOf(b.priority));if(ui.sort==='Newest')list.sort((a,b)=>b.created.localeCompare(a.created));if(ui.sort==='Oldest')list.sort((a,b)=>a.created.localeCompare(b.created));if(ui.direction==='desc')list.reverse();return list}
  function issuesPage(title,subtitle,isMy=false){let tabs=isMy?['Assigned','Created','Subscribed','Activity']:['All','Active','Backlog','Completed'];if(!tabs.includes(ui.tab))ui.tab=tabs[0];const list=filteredIssues();return `${head(title,subtitle,`<button class="text-button" data-action="filter-menu">${icons.filter} Filter</button>${newIssueButton()}`)}<div class="tabbar">${tabs.map(t=>`<button class="tab ${ui.tab===t?'active':''}" data-action="tab" data-tab="${t}">${t}${t===ui.tab?`<span class="tab-count">${list.length}</span>`:''}</button>`).join('')}<span class="tabs-spacer"></span></div><div class="toolbar"><button class="filter-button ${Object.values(ui.filters).some(Boolean)?'selected':''}" data-action="filter-menu">${icons.filter} Filter${Object.values(ui.filters).some(Boolean)?' · Active':''}</button>${Object.entries(ui.filters).filter(([,v])=>v).map(([k,v])=>`<button class="property-pill" data-action="clear-filter" data-key="${k}">${esc(v)} ${icons.close}</button>`).join('')}<span class="toolbar-spacer"></span><span class="sort-label">${esc(ui.group)} · ${esc(ui.sort)}</span><button class="icon-btn" data-action="display-menu" title="Display options">${icons.display}</button><span class="tool-split"></span><button class="icon-btn ${ui.layout==='list'?'active':''}" data-action="set-layout" data-layout="list" title="List">${icons.list}</button><button class="icon-btn ${ui.layout==='board'?'active':''}" data-action="set-layout" data-layout="board" title="Board">${icons.board}</button></div>${window.LinearWorkflows?.bulkToolbar()||''}${ui.layout==='board'?board(list):issueGroups(list)}`}
