  function board(list){const groups=ui.group==='Status'?[...new Set([...statusNames(ui.page==='my'?undefined:ui.teamId),...list.map(i=>i.status)])].filter(s=>s!=='Triage'&&list.some(i=>i.status===s)):[...new Set(list.map(i=>groupValue(i,ui.group)))];return `<div class="board">${groups.map(g=>`<div class="board-col" data-drop-group="${esc(g)}"><div class="board-col-head">${ui.group==='Status'?statusIcon(g):ui.group==='Priority'?priorityIcon(g):'<span class="project-dot"></span>'}<span>${esc(g)}</span><span class="count">${list.filter(i=>groupValue(i,ui.group)===g).length}</span><button class="icon-btn" data-action="new-issue" data-status="${ui.group==='Status'&&statusNames(ui.teamId).includes(g)?g:defaultStatus(ui.teamId)}">${icons.plus}</button></div><div class="board-cards">${list.filter(i=>groupValue(i,ui.group)===g).map(i=>`<div class="board-card" data-action="open-issue" data-id="${i.id}" draggable="true" data-drag-id="${i.id}"><div class="board-card-title">${esc(i.title)}</div><div class="board-card-foot"><span>${i.id}</span>${priorityIcon(i.priority)}${avatar(i.assignee,true)}</div></div>`).join('')}</div><button class="board-add" data-action="new-issue" data-status="${ui.group==='Status'&&statusNames(ui.teamId).includes(g)?g:defaultStatus(ui.teamId)}">${icons.plus} New issue</button></div>`).join('')}</div>`}
  function empty(title,description,action,label){return `<div class="empty"><div class="empty-icon">${icons.issue}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<button class="subtle-button" data-action="${action}">${icons.plus} ${esc(label)}</button>`:''}</div>`}
