  function cyclesPage(){const cycles=data.cycles.filter(c=>c.teamId===ui.teamId);return `${head('Cycles','Keep work moving with a focused cadence.',``)}<div class="tabbar"><button class="tab active">All cycles</button></div><div class="cycle-list">${cycles.map(c=>{let issues=data.issues.filter(i=>i.cycle===c.name&&i.teamId===ui.teamId);let done=issues.filter(completed).length;let pct=issues.length?Math.round(done/issues.length*100):0;return `<div class="cycle-card" data-action="open-cycle" data-name="${esc(c.name)}"><span class="cycle-badge">${icons.cycle}</span><div class="cycle-info"><div class="cycle-name">${esc(c.name)} ${c.current?'<span class="label-pill" style="margin-left:7px;color:#bbaaff">Current</span>':''}</div><div class="cycle-meta">${esc(c.start)} – ${esc(c.end)} · ${issues.length} issues</div></div><div class="cycle-progress"><div class="cycle-meta">${pct}% complete</div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div>${icons.chevron}</div>`}).join('')}</div>`}
