  function teamPage(){const team=selectedTeam(),issues=data.issues.filter(i=>i.teamId===ui.teamId),projects=data.projects.filter(p=>(p.teamIds||[p.teamId]).includes(ui.teamId)),cycles=data.cycles.filter(c=>c.teamId===ui.teamId);return `${head(team?.name||'Team',`${team?.visibility||'public'} team · ${team?.key||''}`,newIssueButton())}<div class="tabbar"><button class="tab active">Overview</button></div><div class="stat-grid"><div class="stat-card"><div class="stat-label">Active issues</div><div class="stat-value">${issues.filter(i=>['unstarted','started'].includes(statusCategory(i.status,i.teamId))).length}</div><div class="stat-detail">Across team projects</div></div><div class="stat-card"><div class="stat-label">Projects</div><div class="stat-value">${projects.length}</div><div class="stat-detail">${projects.filter(p=>p.status==='In Progress').length} in progress</div></div><div class="stat-card"><div class="stat-label">Current cycle</div><div class="stat-value" style="font-size:18px">${esc(cycles.find(c=>c.current)?.name||'None')}</div><div class="stat-detail">${issues.filter(i=>i.cycle===cycles.find(c=>c.current)?.name).length} issues planned</div></div></div><div class="detail-section-title">Quick access</div><div class="view-list">${[['Issues','Manage the team backlog','issues'],['Cycles','Plan work in focused intervals','cycles'],['Projects','See all team projects','team-projects']].map(([name,desc,page])=>`<div class="view-card" data-action="navigate" data-page="${page}">${icons[name.toLowerCase()==='issues'?'issue':name.toLowerCase()==='cycles'?'cycle':'project']}<div><div class="view-title">${name}</div><div class="view-description">${desc}</div></div>${icons.chevron}</div>`).join('')}</div>`}
