    const choices=field==='status'?statusNames(teamId,!!enterprise?.teams.find(t=>t.id===teamId)?.triage_enabled):field==='priority'?priorities:field==='assignee'?[{id:'',name:'Unassigned'},...assigneeChoices(teamId)]:field==='project'?[{id:'',name:'No project'},...data.projects.filter(p=>(p.teamIds||[p.teamId]).includes(teamId)).map(p=>({id:p.id,name:p.name}))]:field==='cycle'?['No cycle',...data.cycles.filter(c=>c.teamId===teamId).map(c=>c.name)]:field==='labels'?['Bug','Feature','Design','Improvement','Accessibility']:[];
    const current=scope==='draft'?draft[field==='assignee'?'assigneeId':field==='project'?'projectId':field]:field==='assignee'?issueBy(entityId)?.assigneeId:field==='project'?issueBy(entityId)?.projectId:issueBy(entityId)?.[field];
