    const content=mode==='react'?`<div class="comment-emoji-choices">${['👍','❤️','🎉','👀','🚀','👎'].map(emoji=>`<button data-action="comment-react" data-id="${esc(issueId)}" data-comment="${esc(commentId)}" data-emoji="${emoji}">${emoji}</button>`).join('')}</div>`:`<textarea id="comment-dialog-input" class="modal-desc" placeholder="Write a ${mode==='reply'?'reply':'comment'}...">${mode==='edit'?esc(comment.text):''}</textarea>`;
    modal(`<div class="modal-head"><span>${title}</span><button class="icon-btn" data-action="close-modal">${icons.close}</button></div><div class="modal-body">${content}</div><div class="modal-footer"><span class="spacer"></span><button class="subtle-button" data-action="open-issue" data-id="${esc(issueId)}">Cancel</button>${mode==='react'?'':`<button class="primary-button" data-action="comment-save" data-mode="${mode}" data-id="${esc(issueId)}" data-comment="${esc(commentId)}">${mode==='reply'?'Reply':'Save'}</button>`}</div>`,'compact');
