  function openIssue(issueId){const i=issueBy(issueId);if(!i)return;if(location.hash!==`#issue/${encodeURIComponent(issueId)}`){if(!location.hash.startsWith('#issue/'))ui.issueReturnHash=location.hash||'#issues';history.pushState({issueId},'',`#issue/${encodeURIComponent(issueId)}`)}ui.issueId=issueId;document.title=`${i.id} ${i.title} – Linear Workspace`;modal(`<div class="modal-head">${statusIcon(i.status,i.teamId)}<span>${esc(enterprise?.teams.find(t=>t.id===i.teamId)?.name||'Team')}</span>${icons.chevron}<span>${i.id}</span><button class="icon-btn" data-action="copy-issue" data-id="${i.id}" title="Copy issue link">${icons.arrow}</button><button class="icon-btn" data-action="issue-more" data-id="${i.id}">${icons.more}</button><button class="icon-btn" data-action="close-modal">${icons.close}</button></div><div class="issue-detail-grid"><div class="issue-detail-main"><div class="issue-detail-id">${i.id} · ${esc(i.status)}</div><textarea class="issue-detail-title" data-change="issue-title" data-id="${i.id}" rows="2">${esc(i.title)}</textarea><textarea class="issue-detail-desc" data-change="issue-desc" data-id="${i.id}" placeholder="Add description...">${esc(i.description)}</textarea>${window.LinearWorkflows?.issuePanel(i)||''}<div class="activity-title">Linked integrations</div><div class="attachment-list">${(enterprise.integrationLinks||[]).filter(link=>link.issueId===i.id).map(link=>{const m=link.metadata||{};const href=typeof m.url==='string'&&/^https:\/\/(github\.com|api\.github\.com)(?:\/|$)/.test(m.url)?m.url:'';return `<div class="attachment-item">${href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${icons.arrow}<span>${esc(link.provider)} · ${esc(m.title||m.message||m.repository||link.kind)}</span></a>`:`<span>${esc(link.provider)} · ${esc(link.kind)}</span>`}<small>${esc(m.state||'')}</small></div>`}).join('')||'<p class="enterprise-muted">No linked pull requests, commits, or Slack threads.</p>'}</div><div class="activity-title">Attachments</div><div class="attachment-list">${(i.attachments||[]).map(a=>`<div class="attachment-item"><a href="/api/files?issue=${encodeURIComponent(i.id)}&id=${encodeURIComponent(a.id)}">${icons.arrow}<span>${esc(a.name)}</span></a><small>${Math.ceil(a.size/1024)} KB</small><button class="icon-btn" data-action="attachment-delete" data-issue="${esc(i.id)}" data-id="${esc(a.id)}" title="Remove attachment">${icons.close}</button></div>`).join('')||'<p class="enterprise-muted">No files attached.</p>'}</div><label class="subtle-button attachment-upload">${icons.plus} Attach file<input type="file" data-change="attachment-upload" data-id="${esc(i.id)}" hidden></label><div class="activity-title">Activity</div><div data-issue-activity="${esc(i.id)}"><p class="enterprise-muted">Loading history…</p></div>${commentMarkup(i)}</div><div class="issue-detail-side"><div class="side-prop-label">Properties</div>${['status','priority','assignee','project','cycle'].map(f=>`<button class="side-prop" data-action="issue-menu" data-field="${f}" data-id="${i.id}">${f==='status'?statusIcon(i.status,i.teamId):f==='priority'?priorityIcon(i.priority):f==='assignee'?avatar(i.assignee,true):f==='project'?icons.project:icons.cycle}<span>${esc(i[f]||({assignee:'Unassigned',project:'Add to project',cycle:'Add to cycle'})[f])}</span></button>`).join('')}<div class="side-prop-label">Labels</div><button class="side-prop" data-action="issue-menu" data-field="labels" data-id="${i.id}">${icons.tag}<span>${i.labels?.length?esc(i.labels.join(', ')):'Add labels'}</span></button><div class="side-prop-label">Details</div><div class="side-prop" style="cursor:default">${icons.calendar}<span>Created ${esc(i.created)}</span></div></div></div>`,'detail-modal');loadIssueActivity(issueId)}
